  // ============ Validation ============
  public static void validateConfig(Grpcconfig.Config msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate instanceId (assert_max_length: 128)
    if (msg.getInstanceId().length() > 128) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field instanceId must be at most 128 characters, got: %d",
              msg.getInstanceId().length()));
    }
    // Validate maxRequestSize (assert_gt: 0)
    if (msg.getMaxRequestSize() <= 0L) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field maxRequestSize must be > 0, got: %s", msg.getMaxRequestSize()));
    }
    // Validate requestTimeoutSeconds (assert_duration: POSITIVE)
    if (msg.getRequestTimeoutSeconds() <= 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field requestTimeoutSeconds must be positive (> 0), got: %d",
              msg.getRequestTimeoutSeconds()));
    }
    // Validate shutdownTimeoutSeconds (assert_duration: POSITIVE)
    if (msg.getShutdownTimeoutSeconds() <= 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field shutdownTimeoutSeconds must be positive (> 0), got: %d",
              msg.getShutdownTimeoutSeconds()));
    }
  }

  public static void validateLogMessage(Grpcconfig.LogMessage msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate message (assert_required)
    if (msg.getMessage().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field message is required");
    }
    // Validate message (assert_max_length: 4096)
    if (msg.getMessage().length() > 4096) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field message must be at most 4096 characters, got: %d", msg.getMessage().length()));
    }
  }

