  /** Applies default values to zero-valued fields of Config. */
  public static Grpcconfig.Config.Builder configDefaults(Grpcconfig.Config msg) {
    if (msg == null) {
      return null;
    }
    Grpcconfig.Config.Builder builder = msg.toBuilder();
    if (msg.getPingIntervalMs() == 0) {
      builder.setPingIntervalMs((int) Helpers.DEFAULT_PING_INTERVAL_MS);
    }
    if (msg.getRebalanceIntervalMs() == 0) {
      builder.setRebalanceIntervalMs((int) Helpers.DEFAULT_REBALANCE_INTERVAL_MS);
    }
    if (!msg.hasListenAddress()) {
      builder.setListenAddress(
          HostOuterClass.Host.newBuilder().setHost("0.0.0.0").setPort(8443).build());
    }
    if (msg.getMaxRequestSize() == 0) {
      builder.setMaxRequestSize(Helpers.DEFAULT_MAX_REQUEST_SIZE);
    }
    if (msg.getRequestTimeoutSeconds() == 0) {
      builder.setRequestTimeoutSeconds(Helpers.DEFAULT_REQUEST_TIMEOUT_SECONDS);
    }
    if (msg.getShutdownTimeoutSeconds() == 0) {
      builder.setShutdownTimeoutSeconds(Helpers.DEFAULT_SHUTDOWN_TIMEOUT_SECONDS);
    }
    return builder;
  }

