  /** Resets Config fields that match defaults back to zero for minimal persistence. */
  public static Grpcconfig.Config.Builder configUndefaults(Grpcconfig.Config msg) {
    if (msg == null) {
      return null;
    }
    Grpcconfig.Config.Builder builder = msg.toBuilder();
    if (msg.getPingIntervalMs() == Helpers.DEFAULT_PING_INTERVAL_MS) {
      builder.setPingIntervalMs(0);
    }
    if (msg.getRebalanceIntervalMs() == Helpers.DEFAULT_REBALANCE_INTERVAL_MS) {
      builder.setRebalanceIntervalMs(0);
    }
    if (msg.hasListenAddress()
        && msg.getListenAddress().getHost().equals("0.0.0.0")
        && msg.getListenAddress().getPort() == 8443) {
      builder.clearListenAddress();
    }
    if (msg.getMaxRequestSize() == Helpers.DEFAULT_MAX_REQUEST_SIZE) {
      builder.setMaxRequestSize(0);
    }
    if (msg.getRequestTimeoutSeconds() == Helpers.DEFAULT_REQUEST_TIMEOUT_SECONDS) {
      builder.setRequestTimeoutSeconds(0);
    }
    if (msg.getShutdownTimeoutSeconds() == Helpers.DEFAULT_SHUTDOWN_TIMEOUT_SECONDS) {
      builder.setShutdownTimeoutSeconds(0);
    }
    return builder;
  }

