  public static Grpcconfig.PingResponse.Builder mergePingResponse(
      Grpcconfig.PingResponse dst, Grpcconfig.PingResponse src) {
    Grpcconfig.PingResponse.Builder builder = dst.toBuilder();
    if (dst.getStatusValue() == 0) {
      builder.setStatusValue(src.getStatusValue());
    }
    return builder;
  }

  public static Grpcconfig.ServiceConfigState.Builder mergeServiceConfigState(
      Grpcconfig.ServiceConfigState dst, Grpcconfig.ServiceConfigState src) {
    Grpcconfig.ServiceConfigState.Builder builder = dst.toBuilder();
    if (!dst.hasConfig() && src.hasConfig()) {
      builder.setConfig(src.getConfig());
    } else if (dst.hasConfig() && src.hasConfig()) {
      builder.setConfig(mergeConfig(dst.getConfig(), src.getConfig()).build());
    }
    return builder;
  }

  // ============ EnvVar ============
  public static Map<String, String> configToEnvVar(Grpcconfig.Config msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_CONFIG_INSTANCE_ID", msg.getInstanceId());
    if (msg.hasPrivateKey()) {
      result.putAll(
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.key.Helpers
              .keyToEnvVar(msg.getPrivateKey()));
    }
    result.put("PROTO_CONFIG_PING_INTERVAL_MS", String.valueOf(msg.getPingIntervalMs()));
    result.put("PROTO_CONFIG_REBALANCE_INTERVAL_MS", String.valueOf(msg.getRebalanceIntervalMs()));
    if (msg.hasListenAddress()) {
      result.putAll(
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.host.Helpers
              .hostToEnvVar(msg.getListenAddress()));
    }
    result.put("PROTO_CONFIG_MAX_REQUEST_SIZE", String.valueOf(msg.getMaxRequestSize()));
    result.put(
        "PROTO_CONFIG_REQUEST_TIMEOUT_SECONDS", String.valueOf(msg.getRequestTimeoutSeconds()));
    if (msg.hasLogger()) {
      result.putAll(
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.logger.Helpers
              .loggerConfigToEnvVar(msg.getLogger()));
    }
    result.put(
        "PROTO_CONFIG_SHUTDOWN_TIMEOUT_SECONDS", String.valueOf(msg.getShutdownTimeoutSeconds()));
    return result;
  }

  public static Grpcconfig.Config.Builder configFromEnvVar(Map<String, String> env) {
    Grpcconfig.Config.Builder builder = Grpcconfig.Config.newBuilder();
    String val;
    val = env.get("PROTO_CONFIG_INSTANCE_ID");
    if (val != null && !val.isEmpty()) {
      builder.setInstanceId(val);
    }
    {
      var sub =
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.key.Helpers
              .keyFromEnvVar(env)
              .build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setPrivateKey(sub);
      }
    }
    val = env.get("PROTO_CONFIG_PING_INTERVAL_MS");
    if (val != null && !val.isEmpty()) {
      builder.setPingIntervalMs(Integer.parseInt(val));
    }
    val = env.get("PROTO_CONFIG_REBALANCE_INTERVAL_MS");
    if (val != null && !val.isEmpty()) {
      builder.setRebalanceIntervalMs(Integer.parseInt(val));
    }
    {
      var sub =
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.host.Helpers
              .hostFromEnvVar(env)
              .build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setListenAddress(sub);
      }
    }
    val = env.get("PROTO_CONFIG_MAX_REQUEST_SIZE");
    if (val != null && !val.isEmpty()) {
      builder.setMaxRequestSize(Long.parseLong(val));
    }
    val = env.get("PROTO_CONFIG_REQUEST_TIMEOUT_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setRequestTimeoutSeconds(Long.parseLong(val));
    }
    {
      var sub =
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.logger.Helpers
              .loggerConfigFromEnvVar(env)
              .build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setLogger(sub);
      }
    }
    val = env.get("PROTO_CONFIG_SHUTDOWN_TIMEOUT_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setShutdownTimeoutSeconds(Long.parseLong(val));
    }
    return builder;
  }

